"  const selectPosTable = (table) => {
    // Save the current mode cart before switching to a table
    saveCurrentCartForMode(orderType, activeTrayTab, selectedTable, cart);

    if (selectedTable) {
      setTableWaiters(prev => ({ ...prev, [selectedTable.id]: selectedWaiter }));
      setTableDiscounts(prev => ({ ...prev, [selectedTable.id]: discount }));
      setTableAdditionalCharges(prev => ({ ...prev, [selectedTable.id]: appliedAdditionalCharges }));
    }

    setSelectedTable(table);

    const restoredWaiter = tableWaiters[table.id] || null;
    const restoredDiscount = tableDiscounts[table.id] || { type: 'NONE', value: 0 };
    const restoredCharges = tableAdditionalCharges[table.id] || [];

    setSelectedWaiter(restoredWaiter);
    setDiscount(restoredDiscount);
    setSelectedDiscountId(restoredDiscount.id || (restoredDiscount.value ? 'custom' : null));
    setAppliedAdditionalCharges(restoredCharges);

    if (table.is_temporary && (tableBills[table.id] || []).filter(item => !item.isCancelled).length > 0) {
      setCart([...tableBills[table.id]]);
    } else {
      setCart(tableCarts[table.id] || []);
    }"

